Given a head of the linked list, Insert a new node at the beginning/start/front of the linked list.Example:Input: x = 1 Output: 1 -> 2 -> 3 -> 4 -> 5Explanation: We can see that 1 is inserted at the beginning of the linked list. Input: x = 1 Output:  1 -> 2 -> 10Explanation: We can see that 1 is inserted at the beginning of the linked list. Try It YourselfApproach:To insert a new node at the front, we create a new node and point its next reference to the current head of the linked list. Then, we update the head to be this new node. This operation is efficient because it only requires adjusting a few pointers.Algorithm:Make the first node of Linked List linked to the new nodeRemove the head from the original first node of Linked ListMake the new node as the Head of the Linked List.Below is the implementation of the approach:
            C++

    #include <iostream>
using namespace std;

// Define a node in the linked list
class Node {
public:
    int data;
    Node* next;

    // Constructor to initialize the node
    Node(int x) {
        data = x;
        next = nullptr;
    }
};

// Function to insert a new node
// at the beginning of the list
Node* insertAtFront(Node* head, int x) {
    Node* newNode = new Node(x);
    newNode->next = head;
    return newNode;
}

void printList(Node* head) {
    Node* curr = head;

    while (curr != nullptr) {
        cout << curr->data;
        if (curr->next != nullptr) {
            cout << " -> ";
        }
        curr = curr->next;
    }
    cout << endl;
}

int main() {
    // Create the linked list 2->3->4->5
    Node* head = new Node(2);
    head->next = new Node(3);
    head->next->next = new Node(4);
    head->next->next->next = new Node(5);

    // Insert a new node at the front of the list
    int x = 1;
    head = insertAtFront(head, x);

    printList(head);

    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>

// Define a node in the linked list
struct Node
{
    int data;
    struct Node *next;
};

// Function to create a new node
struct Node *createNode(int x)
{
    struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));
    newNode->data = x;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a new node at the beginning of the list
struct Node *insertAtFront(struct Node *head, int x)
{
    struct Node *newNode = createNode(x);
    newNode->next = head;
    return newNode;
}

// Function to print the linked list
void printList(struct Node *head)
{
    struct Node *curr = head;
    while (curr != NULL)
    {
        printf("%d", curr->data);
        if (curr->next != NULL)
            printf(" -> ");
        curr = curr->next;
    }
    printf("\n");
}

int main()
{
    // Create the linked list 2->3->4->5
    struct Node *head = createNode(2);
    head->next = createNode(3);
    head->next->next = createNode(4);
    head->next->next->next = createNode(5);

    // Insert a new node at the front
    int x = 1;
    head = insertAtFront(head, x);

    // Print the updated linked list
    printList(head);

    return 0;
}


